import{z as d,x as A,o as E,c as p,q as o,j as i,D as e,d as t,s,S as l,b as n}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"HKDF","description":"","frontmatter":{"title":"HKDF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hkdf.md","filePath":"cs/hkdf.md","lastUpdated":1791063341000}'),D={name:"cs/hkdf.md"};function K(c,a,h,f,B,m){const r=A("Mermaid");return E(),p("div",null,[a[2]||(a[2]=o('<h1 id="hkdf" tabindex="-1">HKDF <a class="header-anchor" href="#hkdf" aria-label="Permalink to &quot;HKDF&quot;">​</a></h1><div class="epigraph"><p>HKDF 先用 HMAC 提取，把不匀的输入密钥材料收成伪随机密钥，再扩展出多条用途分离的输出。它不是慢哈希，也不从弱口令里变出熵。</p><footer>—— Krawczyk, Cryptographic Extraction and Key Derivation, 2010；RFC 5869</footer></div><p>上一课<a href="/cs/csprng">CSPRNG</a>从熵池抽新鲜随机。缺口是<strong>已经有共享秘密</strong>（ECDH 输出、PSK）时如何派生 AEAD 键、IV 盐、下一跳棘轮键。主干<a href="/cs/kdf-slow-hash">KDF 与慢哈希</a>管口令；本课 HKDF 管高熵 IKM。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ECDH 的共享坐标不是均匀密钥。直接截断当 AES 键会留结构。HKDF-Extract(salt, IKM)→PRK，HKDF-Expand(PRK, info, L)→OKM。<code>info</code> 做域分离：同一 IKM 不能在两条协议里撞键。缺口是提取–扩展，不是再讲 bcrypt。</p><h3 id="不能当口令哈希" tabindex="-1">不能当口令哈希 <a class="header-anchor" href="#不能当口令哈希" aria-label="Permalink to &quot;不能当口令哈希&quot;">​</a></h3><p>口令熵低，要慢哈希与盐。HKDF 快，假设 IKM 已有足够熵。</p><p><span class="marginnote">RFC 5869。TLS 1.3 的 HKDF-Expand-Label 是加了标签的扩展。Signal 棘轮更后用同一思想。</span></p><p><span class="marginnote">直觉类比：Extract 像把成色不匀的金料（ECDH 输出带结构）统一熔成一根标准金条（PRK）；Expand 再当模具，从金条上压出一枚枚不同用途的硬币——info 标签就是币面上的「面值」，不同面值互不通用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 Extract 与 Expand。强调 salt 与 info 的角色。对照：ChaCha/AES 的密钥从 OKM 切开，nonce 另计。指出长度扩展已由 HMAC 关。</p>',12)),(E(),i(l,null,{default:e(()=>[s(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IKM%5B%22ECDH%20%E7%AD%89%20IKM%22%5D%20--%3E%20EX%5B%22HKDF-Extract%22%5D%0A%20%20SALT%5B%22%E7%9B%90%22%5D%20--%3E%20EX%0A%20%20EX%20--%3E%20PRK%5B%22PRK%22%5D%0A%20%20PRK%20--%3E%20EXP%5B%22HKDF-Expand%20%2B%20info%22%5D%0A%20%20EXP%20--%3E%20OKM%5B%22%E7%94%A8%E9%80%94%E5%88%86%E7%A6%BB%E7%9A%84%E9%94%AE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"域分离让「同一共享秘密」长出握手密钥、应用密钥、导出密钥而不串用。这是协议级构造的零件。密钥如何存放、谁能碰，下一课 HSM 与生命周期——算法再对，内存里的明文键仍是威胁模型里的端点。",-1)),(E(),i(l,null,{default:e(()=>[s(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRK%5B%22%E5%90%8C%E4%B8%80%E6%8A%8A%20PRK%22%5D%20--%3E%20E1%5B%22Expand%3A%20info%20%3D%20%E6%8F%A1%E6%89%8B%E6%A0%87%E7%AD%BE%22%5D%0A%20%20PRK%20--%3E%20E2%5B%22Expand%3A%20info%20%3D%20%E5%BA%94%E7%94%A8%E6%95%B0%E6%8D%AE%E6%A0%87%E7%AD%BE%22%5D%0A%20%20PRK%20--%3E%20E3%5B%22Expand%3A%20info%20%3D%20%E6%81%A2%E5%A4%8D%E4%BC%9A%E8%AF%9D%E6%A0%87%E7%AD%BE%22%5D%0A%20%20E1%20--%3E%20K1%5B%22%E6%8F%A1%E6%89%8B%E6%B5%81%E9%87%8F%E5%AF%86%E9%92%A5%22%5D%0A%20%20E2%20--%3E%20K2%5B%22%E5%BA%94%E7%94%A8%E6%95%B0%E6%8D%AE%E5%AF%86%E9%92%A5%22%5D%0A%20%20E3%20--%3E%20K3%5B%22%E4%BC%9A%E8%AF%9D%E6%81%A2%E5%A4%8D%E5%AF%86%E9%92%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">数字实例：以 SHA-256 为例，Extract 输出 32 字节 PRK。若应用要一把 AES-256 键（32 字节）加 12 字节 IV，Expand 第一轮 T1 = HMAC(PRK, info‖0x01) 取 32 字节当键；不够再算 T2 = HMAC(PRK, T1‖info‖0x02) 拼接后切出 12 字节 IV。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Argon2 重写一遍。原语课序到 HKDF 收口；下一课序协议级构造从密钥管理与 HSM 起，问「键在哪」。</p><p><span class="marginnote">常见误区：把 HKDF 当「口令加密」工具。它假设输入已有高熵——人选的口令往往只有几十比特熵，字典撞库跑得飞快；口令场景要交给 Argon2 一类带盐慢哈希，HKDF 只伺候 ECDH 输出、PSK 这种材料。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CSPRNG 产熵；HKDF 从已有 IKM 提取并扩展。</li><li>info 做域分离；不能当慢口令哈希。</li><li>TLS 1.3 与棘轮都吃 HKDF。</li><li>下一课序：密钥管理与 HSM。</li><li>出处：Krawczyk, 2010；RFC 5869；对照 RFC 8446。</li></ul>',6))])}const F=d(D,[["render",K]]);export{x as __pageData,F as default};
